import {clone,uid,I,worldPath} from './core.js';
import {nearestOnCubic,splitCubic} from './bezier.js';
export function smoothAnchors(o,amount=55){if(!Number.isFinite(amount))throw Error('Suavizado inválido.');const t=Math.max(0,Math.min(1,amount/100));if(!t)return o;for(const sp of [o,...o.subpaths||[]]){const orig=clone(sp.nodes),n=orig.length;if(n<3)continue;for(let i=0;i<n;i++){if(!sp.closed&&(i===0||i===n-1))continue;const prev=orig[(i+n-1)%n],next=orig[(i+1)%n],p=orig[i],dx=next.x-prev.x,dy=next.y-prev.y,len=Math.hypot(dx,dy);if(len<1e-12)continue;const a=Math.hypot(p.x-prev.x,p.y-prev.y)/3,b=Math.hypot(next.x-p.x,next.y-p.y)/3,mix=(h,x,y)=>({x:(h||p).x*(1-t)+x*t,y:(h||p).y*(1-t)+y*t});sp.nodes[i].in=mix(p.in,p.x-dx/len*a,p.y-dy/len*a);sp.nodes[i].out=mix(p.out,p.x+dx/len*b,p.y+dy/len*b);sp.nodes[i].kind='smooth';}}return o;}
export function cleanPath(o,tolerance=.001){for(const sp of [o,...o.subpaths||[]]){for(let i=sp.nodes.length-1;i>0;i--){const a=sp.nodes[i-1],b=sp.nodes[i];if(Math.hypot(a.x-b.x,a.y-b.y)<=tolerance&&(!a.out||Math.hypot(a.out.x-a.x,a.out.y-a.y)<=tolerance)&&(!b.in||Math.hypot(b.in.x-b.x,b.in.y-b.y)<=tolerance)){a.out=b.out;sp.nodes.splice(i,1);}}for(let i=sp.nodes.length-2;i>0;i--){const a=sp.nodes[i-1],b=sp.nodes[i],c=sp.nodes[i+1],dx=c.x-a.x,dy=c.y-a.y,len=Math.hypot(dx,dy),dot=(b.x-a.x)*dx+(b.y-a.y)*dy;if(!a.out&&!b.in&&!b.out&&!c.in&&len>0&&dot>=0&&dot<=len*len&&Math.abs((b.x-a.x)*dy-(b.y-a.y)*dx)/len<=tolerance)sp.nodes.splice(i,1);}}return o;}
export function nearestPathPoint(o,p){const w=worldPath(o);let best=null;for(let s=0;s<[w,...w.subpaths||[]].length;s++){const sp=[w,...w.subpaths||[]][s];for(let i=0;i<sp.nodes.length-(sp.closed?0:1);i++){const hit=nearestOnCubic(sp.nodes[i],sp.nodes[(i+1)%sp.nodes.length],p);if(!best||hit.distance<best.distance)best={...hit,index:i,subpath:s};}}return best;}
export function scissorsAt(o,p,tolerance=5){if(o.closed||o.subpaths?.length||o.source||o.panelOf||o.construction||o.component||o.modifiers?.length||o.garmentSurface||o.category==='structure'||o.symmetry)throw Error('Las tijeras trabajan sobre trazados abiertos independientes. Para una pieza usá Crear panel.');const hit=nearestPathPoint(o,p);if(!hit||hit.distance>tolerance)return null;const i=hit.index,t=hit.t;if(i===0&&t<1e-5||i===o.nodes.length-2&&t>1-1e-5)return null;let left,right;if(t<1e-5){left=clone(o.nodes.slice(0,i+1));right=clone(o.nodes.slice(i));}else if(t>1-1e-5){left=clone(o.nodes.slice(0,i+2));right=clone(o.nodes.slice(i+1));}else{const [a,m,b]=splitCubic(o.nodes[i],o.nodes[i+1],t);left=[...clone(o.nodes.slice(0,i)),a,clone(m)];right=[clone(m),b,...clone(o.nodes.slice(i+2))];}delete left.at(-1).out;delete right[0].in;right[0].nid=uid();const part={...clone(o),id:uid(),nodes:right,name:o.name+' · parte'};delete part.mirrorPeer;delete part.instanceOf;delete part.symmetry;o.nodes=left;return part;}
export function compoundPaths(os){if(os.length<2||os.some(o=>o.type!=='path'||!o.closed))throw Error('Seleccioná dos o más formas cerradas.');const ps=os.map(worldPath),o={...clone(ps[0]),id:uid(),name:'Trazado compuesto',matrix:I(),subpaths:ps.flatMap((p,i)=>i?[{nodes:p.nodes,closed:true},...p.subpaths||[]]:p.subpaths||[])};for(const k of ['source','panelOf','panelCuts','regionIds','garmentSurface','surfaceBoundaryIds','structureKey','construction','symmetry','mirrorPeer','instanceOf','component'])delete o[k];o.modifiers=[];o.category='graphic';return o;}
export function releaseCompound(o){if(!o.subpaths?.length)return [];const parts=o.subpaths.map(sp=>({...clone(o),...clone(sp),id:uid(),name:o.name+' · contorno',subpaths:[]}));o.subpaths=[];return parts;}
export function measurePoints(a,b){const dx=b.x-a.x,dy=b.y-a.y;return {distance:Math.hypot(dx,dy),angle:-Math.atan2(dy,dx)*180/Math.PI,dx,dy};}
export function shearMatrix(degrees,x,y){if(!Number.isFinite(degrees)||Math.abs(degrees)>=85)throw Error('El ángulo debe estar entre −85° y 85°.');const k=Math.tan(degrees*Math.PI/180);return [1,0,k,1,-k*y,0];}
export function curvatureNodes(points,closed=false){const o={nodes:points.map(p=>({...p,nid:p.nid||uid()})),closed};smoothAnchors(o,100);for(let i=0;i<points.length;i++)if(points[i].corner){delete o.nodes[i].in;delete o.nodes[i].out;o.nodes[i].kind='corner';}return o.nodes;}
// Nearest endpoint pair joining adapted from VectorCraft pathops/edit.rs (MIT).
export function joinNearest(os,tolerance=.00001){if(!os.length||os.some(o=>o.type!=='path'||o.closed||o.subpaths?.length))throw Error('Seleccioná trazados abiertos simples.');const paths=os.map(worldPath),reverse=p=>{p.nodes.reverse();for(const n of p.nodes){const h=n.in;n.in=n.out;n.out=h;}return p;};while(paths.length>1){let best={distance:Infinity};for(let i=0;i<paths.length;i++)for(let j=i+1;j<paths.length;j++)for(const ei of [0,1])for(const ej of [0,1]){const a=paths[i].nodes[ei?paths[i].nodes.length-1:0],b=paths[j].nodes[ej?paths[j].nodes.length-1:0],distance=Math.hypot(a.x-b.x,a.y-b.y);if(distance<best.distance)best={distance,i,j,ei,ej};}const {i,j,ei,ej}=best,b=paths.splice(j,1)[0],a=paths[i];if(!ei)reverse(a);if(ej)reverse(b);if(best.distance<=tolerance){a.nodes.at(-1).out=b.nodes[0].out;b.nodes.shift();}else {delete a.nodes.at(-1).out;delete b.nodes[0].in;}a.nodes.push(...b.nodes);}const o=paths[0];o.id=uid();o.name='Trazados unidos';o.modifiers=[];for(const key of ['symmetry','mirrorPeer','instanceOf','source','panelOf','garmentSurface','surfaceBoundaryIds','structureKey','component'])delete o[key];return o;}
